        "source.summary.pinnedShort": "You chose {method} in Settings.",
        "source.summary.tableShort": "Official timetable from {authority}.",
        "source.summary.authorityShort": "Follows {authority}.",
        "source.summary.standardShort": "No official timetable here, so the app uses {method}. Your local masjid may differ by a few minutes.",
        "source.summary.pinned": "You chose {method} in Settings. Automatic would follow {follow}.",
        "source.summary.mostUsed": "the method most used here",
        "source.summary.localAuthority": "the local authority",
        "source.summary.table": "Official timetable from {authority}. When it can't be downloaded, the app works it out with the same method.",
        "source.summary.authority": "Follows {authority}, worked out on your phone with their method so it works offline.",
        "source.summary.standardNone": "No official timetable here yet, so the app uses {method}, a widely used international method.",
        "source.summary.standardEnd": "Your local masjid may differ by a few minutes. Always follow your local religious authority.",
        "source.summary.londonShort": "London Unified Prayer Timetable from East London Mosque, followed by many London masjids.",
        "source.summary.london": "London Unified Prayer Timetable from East London Mosque, followed by many London masjids. When it can't be downloaded, the app uses the Moonsighting Committee method. Your local masjid may differ by a few minutes.",
        "source.methodName": "{method} method",
        "source.explainA": "Published by the national or state religious authority, or its exact published method.",
        "source.explainB": "From a named mosque's own timetable, checked against our calculation.",
        "source.explainC": "Method confirmed by two or more independent local contributors.",
        "source.explainD": "Astronomical calculation on your device. The method is shown. Local mosques may differ by a few minutes.",
        "source.explainF": "Worked out from your own observation of the sun's shadow or the sky, with honest ± minutes. Used to learn and to check, never in place of the grades above.",
        "source.kindPublished": "Published timetable",
        "source.kindFormula": "Formula",
        "source.kindCalculated": "Calculated",
        "source.kindMasjid": "Masjid timetable",
        "source.kindExplainPublished": "Copied from the timetable the authority publishes. The app does not work these times out.",
        "source.kindExplainFormula": "Worked out on your device with the authority's own published method. It can differ from their printed timetable by a minute or two.",
        "source.kindExplainCalculated": "Worked out on your device with a widely used international method, because there is no official timetable here for the app to use. Your local masjid may differ by a few minutes.",
        "source.kindExplainMasjid": "From your masjid's own timetable.",
        "source.selangor2027": "Selangor changes to nine district timetables on 1 January 2027. JAKIM has not published the new zone codes yet, so for now these times follow the old zone and can differ from your masjid by a few minutes. We will update the app when JAKIM publishes them. Always follow your masjid and your local religious authority.",
        "travel.sourceTitle": "You are away from {country}",
        "travel.sourceBody": "You chose {method} in Settings, so your times still follow {country}. Here they are worked out with its formula, not read from a published timetable. Follow where you are instead, or keep it if that is what you meant.",
        "travel.sourceFollow": "Follow where I am",
        "method.note.muis": "Majlis Ugama Islam Singapura. Online, the app shows MUIS's official timetable; offline it calculates, never earlier than the official time.",
        "method.note.jakim": "Malaysia's 18° Fajr criterion (since 2019). Online, the app shows JAKIM's official e-Solat timetable for your zone; offline it calculates to within about 2 minutes.",
        "method.note.kemenag": "Kementerian Agama. Online, the app shows Kemenag's official timetable for your city or regency; offline it calculates with offsets fitted on the full 2026 Jakarta, Surabaya and Makassar tables.",
        "method.note.sea": "The 20°/18° convention used across the Malay world. A sensible default where no national timetable exists.",
        "method.note.mwl": "A widely used international method.",
        "method.note.karachi": "Standard across Pakistan, India, Bangladesh and Afghanistan.",
        "method.note.ummalqura": "The official calendar of Saudi Arabia, followed by the Haramain in Makkah and Madinah. Isha is 90 minutes after Maghrib, 120 in Ramadan.",
        "method.note.dubai": "United Arab Emirates convention.",
        "method.note.qatar": "Isha 90 minutes after Maghrib.",
        "method.note.kuwait": "Kuwait convention.",
        "method.note.diyanet": "Diyanet's method (Fajr 18°, Isha 17°, Asr at one shadow length), with precautionary minutes fitted on its published Istanbul timetable. Used by Turkish masjids across Europe too.",
        "method.note.tehran": "Institute of Geophysics, University of Tehran. Maghrib when the sun is 4.5° below the horizon.",
        "method.note.egyptian": "The Egyptian General Authority of Survey. Also common in Syria, Libya and Sudan.",
        "method.note.isna": "The Islamic Society of North America. Followed by many masjids in the United States and Canada.",
        "method.note.moonsighting": "Made for northern countries. Fajr and Isha follow the seasons so summer nights stay workable. Common in the UK, Ireland and North America.",
        "method.note.uoif": "The 12° angle used by Musulmans de France (formerly UOIF). Fajr is later and Isha earlier than most methods.",
        "method.note.russia": "The Spiritual Administration of Muslims of Russia.",
        "method.note.algeria": "The method of Algeria's Ministry of Religious Affairs and Endowments.",
        "method.note.tunisia": "The method of Tunisia's Ministry of Religious Affairs.",
        "method.note.morocco": "The method of Morocco's Ministry of Habous and Islamic Affairs.",
        "method.note.jordan": "The method of Jordan's Ministry of Awqaf and Islamic Affairs. Also used in Palestine.",
        "method.note.icbih": "The Islamic Community of Bosnia and Herzegovina and its Takvim method (Fajr 18°, Isha 16°, Asr at one shadow length), with its minutes of caution at sunrise and sunset, fitted on its published times for Sarajevo. Never earlier than the published time.",
        "method.note.kmsh": "The method of the Muslim Community of Albania, KMSH (Fajr 18°, Isha 17°, Asr at one shadow length), with minutes fitted on its 2026 Tirana calendar. Never earlier than the published time.",
        "method.note.qmdb": "The method of the Spiritual Administration of Muslims of Kazakhstan (QMDB), with Fajr and Isha at 15°, Asr at two shadow lengths, with minutes added at midday, Asr and sunset and taken off at sunrise, more of them from latitude 48° north. Checked against its published formula for a full year.",
        "method.note.muftiyatkg": "The method of the Spiritual Administration of Muslims of Kyrgyzstan, Muftiyat (Fajr 18°, Isha 16°, Asr at two shadow lengths), with minutes fitted on its published 2026 Bishkek calendar. Never earlier than the published time.",
